-- ============================================================
-- Seed 09: Import lead base from gger3k.csv  (2818 unique leads)
--
-- Loads a prospect base into the CRM as public.leads with
-- stage = 'NEW_INQUIRY'. CRM workers then process them through the
-- pipeline (NEW_INQUIRY -> IN_DISCUSSION -> PENDING_KYC -> FUNDED)
-- and convert qualified leads into Trading clients (separate platform).
--
-- Self-contained & idempotent:
--   * adds public.leads.country column if missing
--   * re-running skips emails already present (matched case-insensitively)
--
-- Run in: Supabase SQL Editor (YOUR project) -> New query -> Run
-- ============================================================

-- 1. Ensure country column exists (no-op if already there)
alter table public.leads add column if not exists country text;
create index if not exists leads_country_idx on public.leads(country);

insert into public.leads (first_name, last_name, name, email, phone, country, stage, acquisition_source)
select v.first_name, v.last_name, v.name, v.email, v.phone, v.country, 'NEW_INQUIRY',
       jsonb_build_object('source', v.source, 'country', v.country, 'imported_from', 'gger3k.csv')
